    "section": "1.1",
    "number": 8,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "8. Suppose that Smartphone A has 256 MB RAM and\n32 GB ROM, and the resolution of its camera is 8 MP;\nSmartphone B has 288 MB RAM and 64 GB ROM, and\nthe resolution of its camera is 4 MP; and Smartphone C\nhas 128 MB RAM and 32 GB ROM, and the resolution\nof its camera is 5 MP. Determine the truth value of each\nof these propositions.\na) Smartphone B has the most RAM of these three\nsmartphones.\nb) Smartphone C has more ROM or a higher resolution\ncamera than Smartphone B.\nc) Smartphone B has more RAM, more ROM, and a\nhigher resolution camera than Smartphone A.\nd) If Smartphone B has more RAM and more ROM than\nSmartphone C, then it also has a higher resolution\ncamera.\ne) Smartphone A has more RAM than Smartphone B if\nand only if Smartphone B has more RAM than Smart-\nphone A.",
    "prompt": "8. Suppose that Smartphone A has 256 MB RAM and 32 GB ROM, and the resolution of its camera is 8 MP; Smartphone B has 288 MB RAM and 64 GB ROM, and the resolution of its camera is 4 MP; and Smartphone C has 128 MB RAM and 32 GB ROM, and the resolution of its camera is 5 MP. Determine the truth value of each of these propositions. a) Smartphone B has the most RAM of these three smartphones. b) Smartphone C has more ROM or a higher resolution camera than Smartphone B. c) Smartphone B has more RAM, more ROM, and a higher resolution camera than Smartphone A. d) If Smartphone B has more RAM and more ROM than Smartphone C, then it also has a higher resolution camera. e) Smartphone A has more RAM than Smartphone B if and only if Smartphone B has more RAM than Smartphone A.",
