    "section": "1.1",
    "number": 9,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "9. Suppose that during the most recent ﬁscal year, the an-\nnual revenue of Acme Computer was 138 billion dollars\nand its net proﬁt was 8 billion dollars, the annual revenue\nof Nadir Software was 87 billion dollars and its net proﬁt\nwas 5 billion dollars, and the annual revenue of Quixote\nMedia was 111 billion dollars and its net proﬁt was\n13 billion dollars. Determine the truth value of each of\nthese propositions for the most recent ﬁscal year.\n14 1 / The Foundations: Logic and Proofs\na) Quixote Media had the largest annual revenue.\nb) Nadir Software had the lowest net proﬁt and Acme\nComputer had the largest annual revenue.\nc) Acme Computer had the largest net proﬁt or Quixote\nMedia had the largest net proﬁt.\nd) If Quixote Media had the smallest net proﬁt, then\nAcme Computer had the largest annual revenue.\ne) Nadir Software had the smallest net proﬁt if and only\nif Acme Computer had the largest annual revenue.",
    "prompt": "9. Suppose that during the most recent fiscal year, the annual revenue of Acme Computer was 138 billion dollars and its net profit was 8 billion dollars, the annual revenue of Nadir Software was 87 billion dollars and its net profit was 5 billion dollars, and the annual revenue of Quixote Media was 111 billion dollars and its net profit was 13 billion dollars. Determine the truth value of each of these propositions for the most recent fiscal year. a) Quixote Media had the largest annual revenue. b) Nadir Software had the lowest net profit and Acme Computer had the largest annual revenue. c) Acme Computer had the largest net profit or Quixote Media had the largest net profit. d) If Quixote Media had the smallest net profit, then Acme Computer had the largest annual revenue. e) Nadir Software had the smallest net profit if and only if Acme Computer had the largest annual revenue.",
