    "stars": 0,
    "rawText": "13. Let p and q be the propositions\np: It is below freezing.\nq: It is snowing.\nWrite these propositions using p and q and logical con-\nnectives (including negations).\na) It is below freezing and snowing.\nb) It is below freezing but not snowing.\nc) It is not below freezing and it is not snowing.\nd) It is either snowing or below freezing (or both).\ne) If it is below freezing, it is also snowing.\nf) Either it is below freezing or it is snowing, but it is\nnot snowing if it is below freezing.\ng) That it is below freezing is necessary and suﬃcient\nfor it to be snowing.",
    "prompt": "13. Let p and q be the propositions p: It is below freezing. q: It is snowing. Write these propositions using p and q and logical connectives (including negations). a) It is below freezing and snowing. b) It is below freezing but not snowing. c) It is not below freezing and it is not snowing. d) It is either snowing or below freezing (or both). e) If it is below freezing, it is also snowing. f) Either it is below freezing or it is snowing, but it is not snowing if it is below freezing. g) That it is below freezing is necessary and sufficient for it to be snowing.",
