    "number": 15,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "15. Let p and q be the propositions\np: You drive over 65 miles per hour.\nq: You get a speeding ticket.\nWrite these propositions using p and q and logical con-\nnectives (including negations).\na) You do not drive over 65 miles per hour.\nb) You drive over 65 miles per hour, but you do not get\na speeding ticket.\nc) You will get a speeding ticket if you drive over\n65 miles per hour.\nd) If you do not drive over 65 miles per hour, then you\nwill not get a speeding ticket.\ne) Driving over 65 miles per hour is suﬃcient for getting\na speeding ticket.\nf) You get a speeding ticket, but you do not drive over\n65 miles per hour.\ng) Whenever you get a speeding ticket, you are driving\nover 65 miles per hour.",
    "prompt": "15. Let p and q be the propositions p: You drive over 65 miles per hour. q: You get a speeding ticket. Write these propositions using p and q and logical connectives (including negations). a) You do not drive over 65 miles per hour. b) You drive over 65 miles per hour, but you do not get a speeding ticket. c) You will get a speeding ticket if you drive over 65 miles per hour. d) If you do not drive over 65 miles per hour, then you will not get a speeding ticket. e) Driving over 65 miles per hour is sufficient for getting a speeding ticket. f) You get a speeding ticket, but you do not drive over 65 miles per hour. g) Whenever you get a speeding ticket, you are driving over 65 miles per hour.",
