    "number": 16,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "16. Let p, q,a n dr be the propositions\np: You get an A on the ﬁnal exam.\nq: You do every exercise in this book.\nr:Y o ug e ta nAi nt h i sc l a s s .\nWrite these propositions usingp, q,a n dr and logical con-\nnectives (including negations).\na) You get an A in this class, but you do not do every\nexercise in this book.\nb) Y o ug e ta nAo nt h eﬁ n a l ,y o ud oe v e r ye x e r c i s ei n\nthis book, and you get an A in this class.\nc) To get an A in this class, it is necessary for you to get\nan A on the ﬁnal.\nd) You get an A on the ﬁnal, but you don’t do every ex-\nercise in this book; nevertheless, you get an A in this\nclass.\ne) Getting an A on the ﬁnal and doing every exercise in\nthis book is suﬃcient for getting an A in this class.\nf) You will get an A in this class if and only if you either\ndo every exercise in this book or you get an A on the\nﬁnal.",
    "prompt": "16. Let p, q,a n dr be the propositions p: You get an A on the final exam. q: You do every exercise in this book. r:Y o ug e ta nAi nt h i sc l a s s . Write these propositions usingp, q,a n dr and logical connectives (including negations). a) You get an A in this class, but you do not do every exercise in this book. b) Y o ug e ta nAo nt h efi n a l ,y o ud oe v e r ye x e r c i s ei n this book, and you get an A in this class. c) To get an A in this class, it is necessary for you to get an A on the final. d) You get an A on the final, but you don’t do every exercise in this book; nevertheless, you get an A in this class. e) Getting an A on the final and doing every exercise in this book is sufficient for getting an A in this class. f) You will get an A in this class if and only if you either do every exercise in this book or you get an A on the final.",
