    "number": 17,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "17. Let p, q,a n dr be the propositions\np: Grizzly bears have been seen in the area.\nq: Hiking is safe on the trail.\nr: Berries are ripe along the trail.\nWrite these propositions usingp, q,a n dr and logical con-\nnectives (including negations).\na) Berries are ripe along the trail, but grizzly bears have\nnot been seen in the area.\nb) Grizzly bears have not been seen in the area and hik-\ning on the trail is safe, but berries are ripe along the\ntrail.\nc) If berries are ripe along the trail, hiking is safe if and\nonly if grizzly bears have not been seen in the area.\nd) It is not safe to hike on the trail, but grizzly bears have\nnot been seen in the area and the berries along the trail\nare ripe.\ne) For hiking on the trail to be safe, it is necessary but\nnot suﬃcient that berries not be ripe along the trail\nand for grizzly bears not to have been seen in the area.\n1.1 Propositional Logic 15\nf) Hiking is not safe on the trail whenever grizzly bears\nhave been seen in the area and berries are ripe along\nthe trail.",
    "prompt": "17. Let p, q,a n dr be the propositions p: Grizzly bears have been seen in the area. q: Hiking is safe on the trail. r: Berries are ripe along the trail. Write these propositions usingp, q,a n dr and logical connectives (including negations). a) Berries are ripe along the trail, but grizzly bears have not been seen in the area. b) Grizzly bears have not been seen in the area and hiking on the trail is safe, but berries are ripe along the trail. c) If berries are ripe along the trail, hiking is safe if and only if grizzly bears have not been seen in the area. d) It is not safe to hike on the trail, but grizzly bears have not been seen in the area and the berries along the trail are ripe. e) For hiking on the trail to be safe, it is necessary but not sufficient that berries not be ripe along the trail and for grizzly bears not to have been seen in the area. f) Hiking is not safe on the trail whenever grizzly bears have been seen in the area and berries are ripe along the trail.",
