    "rawText": "25. Write each of these statements in the form “if p,t h e nq”\nin English. [Hint: R e f e rt ot h el i s to fc o m m o nw a y st o\nexpress conditional statements.]\na) It snows whenever the wind blows from the northeast.\nb) The apple trees will bloom if it stays warm for\na week.\nc) That the Pistons win the championship implies that\nthey beat the Lakers.\nd) It is necessary to walk eight miles to get to the top of\nLong’s Peak.\ne) To get tenure as a professor, it is suﬃcient to be world\nfamous.\nf) If you drive more than 400 miles, you will need to\nbuy gasoline.\ng) Your guarantee is good only if you bought your CD\nplayer less than 90 days ago.\nh) Jan will go swimming unless the water is too cold.\ni) We will have a future, provided that people believe in\nscience.",
    "prompt": "25. Write each of these statements in the form “if p,t h e nq” in English. [Hint: R e f e rt ot h el i s to fc o m m o nw a y st o express conditional statements.] a) It snows whenever the wind blows from the northeast. b) The apple trees will bloom if it stays warm for a week. c) That the Pistons win the championship implies that they beat the Lakers. d) It is necessary to walk eight miles to get to the top of Long’s Peak. e) To get tenure as a professor, it is sufficient to be world famous. f) If you drive more than 400 miles, you will need to buy gasoline. g) Your guarantee is good only if you bought your CD player less than 90 days ago. h) Jan will go swimming unless the water is too cold. i) We will have a future, provided that people believe in science.",
