    "rawText": "12. Are these system speciﬁcations consistent? “If the ﬁle\nsystem is not locked, then new messages will be queued.\nIf the ﬁle system is not locked, then the system is func-\ntioning normally, and conversely. If new messages are not\nqueued, then they will be sent to the message buﬀer. If the\nﬁle system is not locked, then new messages will be sent\nto the message buﬀer. New messages will not be sent to\nthe message buﬀer.”",
    "prompt": "12. Are these system specifications consistent? “If the file system is not locked, then new messages will be queued. If the file system is not locked, then the system is functioning normally, and conversely. If new messages are not queued, then they will be sent to the message buffer. If the file system is not locked, then new messages will be sent to the message buffer. New messages will not be sent to the message buffer.”",
