    "setId": "rosen-ch1-exercise-set-1-2",
    "section": "1.2",
    "number": 36,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "36. The police have three suspects for the murder of Mr.\nCooper: Mr. Smith, Mr. Jones, and Mr. Williams. Smith,\nJones, and Williams each declare that they did not kill\nCooper. Smith also states that Cooper was a friend of\nJones and that Williams disliked him. Jones also states\nthat he did not know Cooper and that he was out of town\nthe day Cooper was killed. Williams also states that he\nsaw both Smith and Jones with Cooper the day of the\nkilling and that either Smith or Jones must have killed\nhim. Can you determine who the murderer was if\na) one of the three men is guilty, the two innocent men\nare telling the truth, but the statements of the guilty\nman may or may not be true?\nb) innocent men do not lie?",
    "prompt": "36. The police have three suspects for the murder of Mr. Cooper: Mr. Smith, Mr. Jones, and Mr. Williams. Smith, Jones, and Williams each declare that they did not kill Cooper. Smith also states that Cooper was a friend of Jones and that Williams disliked him. Jones also states that he did not know Cooper and that he was out of town the day Cooper was killed. Williams also states that he saw both Smith and Jones with Cooper the day of the killing and that either Smith or Jones must have killed him. Can you determine who the murderer was if a) one of the three men is guilty, the two innocent men are telling the truth, but the statements of the guilty man may or may not be true? b) innocent men do not lie?",
