    "difficulty": "standard",
    "stars": 0,
    "rawText": "39. A detective has interviewed four witnesses to a crime.\nFrom the stories of the witnesses the detective has con-\ncluded that if the butler is telling the truth then so is the\ncook; the cook and the gardener cannot both be telling\nthe truth; the gardener and the handyman are not both ly-\ning; and if the handyman is telling the truth then the cook\nis lying. For each of the four witnesses, can the detec-\ntive determine whether that person is telling the truth or\nlying? Explain your reasoning.",
    "prompt": "39. A detective has interviewed four witnesses to a crime. From the stories of the witnesses the detective has concluded that if the butler is telling the truth then so is the cook; the cook and the gardener cannot both be telling the truth; the gardener and the handyman are not both lying; and if the handyman is telling the truth then the cook is lying. For each of the four witnesses, can the detective determine whether that person is telling the truth or lying? Explain your reasoning.",
