    "kind": "exercise",
    "set": "1.3",
    "setId": "rosen-ch1-exercise-set-1-3",
    "section": "1.3",
    "number": 46,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "46. Suppose that a truth table in n propositional variables is\nspeciﬁed. Show that a compound proposition with this\ntruth table can be formed by taking the disjunction of\nconjunctions of the variables or their negations, with one\nconjunction included for each combination of values for\nwhich the compound proposition is true. The resulting\ncompound proposition is said to be in disjunctive nor-\nmal form.\nA collection of logical operators is called functionally com-\nplete if every compound proposition is logically equivalent\nto a compound proposition involving only these logical oper-\nators.",
    "prompt": "46. Suppose that a truth table in n propositional variables is specified. Show that a compound proposition with this truth table can be formed by taking the disjunction of conjunctions of the variables or their negations, with one conjunction included for each combination of values for which the compound proposition is true. The resulting compound proposition is said to be in disjunctive normal form. A collection of logical operators is called functionally complete if every compound proposition is logically equivalent to a compound proposition involving only these logical operators.",
