    "setId": "rosen-ch1-exercise-set-1-3",
    "section": "1.3",
    "number": 49,
    "difficulty": "challenging",
    "stars": 1,
    "rawText": "∗49. Show that ¬ and ∨form a functionally complete collec-\ntion of logical operators.\nWe now present a group of exercises that involve the logical\noperators NAND and NOR. The proposition pN A N Dqis true\nwhen eitherp or q, or both, are false; and it is false when bothp\nand q are true. The proposition pN O Rqis true when both\np and q are false, and it is false otherwise. The propositions\npN A N Dqand pN O Rqare denoted byp ∣q and p ↓q, respec-\ntively. (The operators|and ↓are called theSheﬀer stroke and\nthe Peirce arrowafter H. M. Sheﬀer and C. S. Peirce, respec-\ntively.)",
    "prompt": "∗49. Show that ¬ and ∨form a functionally complete collection of logical operators. We now present a group of exercises that involve the logical operators NAND and NOR. The proposition pN A N Dqis true when eitherp or q, or both, are false; and it is false when bothp and q are true. The proposition pN O Rqis true when both p and q are false, and it is false otherwise. The propositions pN A N Dqand pN O Rqare denoted byp ∣q and p ↓q, respectively. (The operators|and ↓are called theSheffer stroke and the Peirce arrowafter H. M. Sheffer and C. S. Peirce, respectively.)",
