    "number": 39,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "39. Express each of these statements using predicates and\nquantiﬁers.\na) A passenger on an airline qualiﬁes as an elite ﬂyer if\nthe passenger ﬂies more than 25,000 miles in a year\nor takes more than 25 ﬂights during that year.\nb) A man qualiﬁes for the marathon if his best previ-\nous time is less than 3 hours and a woman qualiﬁes\nfor the marathon if her best previous time is less than\n3.5 hours.\nc) A student must take at least 60 course hours, or at least\n45 course hours and write a master’s thesis, and re-\nceive a grade no lower than a B in all required courses,\nto receive a master’s degree.\nd) There is a student who has taken more than 21 credit\nhours in a semester and received all A’s.",
    "prompt": "39. Express each of these statements using predicates and quantifiers. a) A passenger on an airline qualifies as an elite flyer if the passenger flies more than 25,000 miles in a year or takes more than 25 flights during that year. b) A man qualifies for the marathon if his best previous time is less than 3 hours and a woman qualifies for the marathon if her best previous time is less than 3.5 hours. c) A student must take at least 60 course hours, or at least 45 course hours and write a master’s thesis, and receive a grade no lower than a B in all required courses, to receive a master’s degree. d) There is a student who has taken more than 21 credit hours in a semester and received all A’s.",
