    "stars": 0,
    "rawText": "42. Express each of these system speciﬁcations using predi-\ncates, quantiﬁers, and logical connectives.\na) When there is less than 30 megabytes free on the hard\ndisk, a warning message is sent to all users.\nb) No directories in the ﬁle system can be opened and\nno ﬁles can be closed when system errors have been\ndetected.\nc) The ﬁle system cannot be backed up if there is a user\ncurrently logged on.\nd) Video on demand can be delivered when there are at\nleast 8 megabytes of memory available and the con-\nnection speed is at least 56 kilobits per second.",
    "prompt": "42. Express each of these system specifications using predicates, quantifiers, and logical connectives. a) When there is less than 30 megabytes free on the hard disk, a warning message is sent to all users. b) No directories in the file system can be opened and no files can be closed when system errors have been detected. c) The file system cannot be backed up if there is a user currently logged on. d) Video on demand can be delivered when there are at least 8 megabytes of memory available and the connection speed is at least 56 kilobits per second.",
