    "rawText": "63. Let P(x), Q(x), R(x), and S(x) be the statements “x is a\nbaby,” “x is logical,” “x is able to manage a crocodile,”\nand “x is despised,” respectively. Suppose that the domain\nconsists of all people. Express each of these statements\nusing quantiﬁers; logical connectives; and P(x), Q(x),\nR(x), and S(x).\na) Babies are illogical.\nb) Nobody is despised who can manage a crocodile.\nc) Illogical persons are despised.\nd) Babies cannot manage crocodiles.\n∗e) Does (d) follow from (a), (b), and (c)? If not, is there\na correct conclusion?",
    "prompt": "63. Let P(x), Q(x), R(x), and S(x) be the statements “x is a baby,” “x is logical,” “x is able to manage a crocodile,” and “x is despised,” respectively. Suppose that the domain consists of all people. Express each of these statements using quantifiers; logical connectives; and P(x), Q(x), R(x), and S(x). a) Babies are illogical. b) Nobody is despised who can manage a crocodile. c) Illogical persons are despised. d) Babies cannot manage crocodiles. ∗e) Does (d) follow from (a), (b), and (c)? If not, is there a correct conclusion?",
