    "number": 12,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "12. Let I(x) be the statement “ x has an Internet connection”\nand C(x, y) be the statement “ x and y have chatted over\nthe Internet,” where the domain for the variables x and y\nconsists of all students in your class. Use quantiﬁers to\nexpress each of these statements.\na) Jerry does not have an Internet connection.\nb) Rachel has not chatted over the Internet with\nChelsea.\nc) Jan and Sharon have never chatted over the Internet.\nd) No one in the class has chatted with Bob.\ne) Sanjay has chatted with everyone except Joseph.\nf) Someone in your class does not have an Internet con-\nnection.\ng) Not everyone in your class has an Internet connec-\ntion.\nh) Exactly one student in your class has an Internet con-\nnection.\ni) Everyone except one student in your class has an In-\nternet connection.\nj) Everyone in your class with an Internet connection\nhas chatted over the Internet with at least one other\nstudent in your class.\nk) Someone in your class has an Internet connection but\nhas not chatted with anyone else in your class.\nl) There are two students in your class who have not\nchatted with each other over the Internet.\nm) There is a student in your class who has chatted with\neveryone in your class over the Internet.\nn) There are at least two students in your class who have\nnot chatted with the same person in your class.\no) There are two students in the class who between them\nhave chatted with everyone else in the class.",
    "prompt": "12. Let I(x) be the statement “ x has an Internet connection” and C(x, y) be the statement “ x and y have chatted over the Internet,” where the domain for the variables x and y consists of all students in your class. Use quantifiers to express each of these statements. a) Jerry does not have an Internet connection. b) Rachel has not chatted over the Internet with Chelsea. c) Jan and Sharon have never chatted over the Internet. d) No one in the class has chatted with Bob. e) Sanjay has chatted with everyone except Joseph. f) Someone in your class does not have an Internet connection. g) Not everyone in your class has an Internet connection. h) Exactly one student in your class has an Internet connection. i) Everyone except one student in your class has an Internet connection. j) Everyone in your class with an Internet connection has chatted over the Internet with at least one other student in your class. k) Someone in your class has an Internet connection but has not chatted with anyone else in your class. l) There are two students in your class who have not chatted with each other over the Internet. m) There is a student in your class who has chatted with everyone in your class over the Internet. n) There are at least two students in your class who have not chatted with the same person in your class. o) There are two students in the class who between them have chatted with everyone else in the class.",
