    "difficulty": "standard",
    "stars": 0,
    "rawText": "13. Let M(x, y)b e“ x has sent y an e-mail message” and\nT(x, y)b e“ x has telephoned y,” where the domain con-\nsists of all students in your class. Use quantiﬁers to ex-\npress each of these statements. (Assume that all e-mail\nmessages that were sent are received, which is not the\nway things often work.)\na) Chou has never sent an e-mail message to Koko.\nb) Arlene has never sent an e-mail message to or tele-\nphoned Sarah.\nc) Jos´e has never received an e-mail message from Deb-\norah.\nd) Every student in your class has sent an e-mail mes-\nsage to Ken.\ne) No one in your class has telephoned Nina.\n70 1 / The Foundations: Logic and Proofs\nf) Everyone in your class has either telephoned Avi or\nsent him an e-mail message.\ng) There is a student in your class who has sent every-\none else in your class an e-mail message.\nh) There is someone in your class who has either sent an\ne-mail message or telephoned everyone else in your\nclass.\ni) There are two diﬀerent students in your class who\nhave sent each other e-mail messages.\nj) There is a student who has sent himself or herself an\ne-mail message.\nk) There is a student in your class who has not received\nan e-mail message from anyone else in the class and\nwho has not been called by any other student in the\nclass.\nl) Every student in the class has either received an e-\nmail message or received a telephone call from an-\nother student in the class.\nm) There are at least two students in your class such that\none student has sent the other e-mail and the second\nstudent has telephoned the ﬁrst student.\nn) There are two diﬀerent students in your class who\nbetween them have sent an e-mail message to or tele-\nphoned everyone else in the class.",
    "prompt": "13. Let M(x, y)b e“ x has sent y an e-mail message” and T(x, y)b e“ x has telephoned y,” where the domain consists of all students in your class. Use quantifiers to express each of these statements. (Assume that all e-mail messages that were sent are received, which is not the way things often work.) a) Chou has never sent an e-mail message to Koko. b) Arlene has never sent an e-mail message to or telephoned Sarah. c) Jos´e has never received an e-mail message from Deborah. d) Every student in your class has sent an e-mail message to Ken. e) No one in your class has telephoned Nina. f) Everyone in your class has either telephoned Avi or sent him an e-mail message. g) There is a student in your class who has sent everyone else in your class an e-mail message. h) There is someone in your class who has either sent an e-mail message or telephoned everyone else in your class. i) There are two different students in your class who have sent each other e-mail messages. j) There is a student who has sent himself or herself an e-mail message. k) There is a student in your class who has not received an e-mail message from anyone else in the class and who has not been called by any other student in the class. l) Every student in the class has either received an email message or received a telephone call from another student in the class. m) There are at least two students in your class such that one student has sent the other e-mail and the second student has telephoned the first student. n) There are two different students in your class who between them have sent an e-mail message to or telephoned everyone else in the class.",
