    "rawText": "16. A discrete mathematics class contains 1 mathematics\nmajor who is a freshman, 12 mathematics majors who\nare sophomores, 15 computer science majors who are\nsophomores, 2 mathematics majors who are juniors, 2\ncomputer science majors who are juniors, and 1 computer\nscience major who is a senior. Express each of these state-\nments in terms of quantiﬁers and then determine its truth\nvalue.\na) There is a student in the class who is a junior.\nb) Every student in the class is a computer science ma-\njor.\nc) There is a student in the class who is neither a math-\nematics major nor a junior.\nd) Every student in the class is either a sophomore or a\ncomputer science major.\ne) There is a major such that there is a student in the\nclass in every year of study with that major.",
    "prompt": "16. A discrete mathematics class contains 1 mathematics major who is a freshman, 12 mathematics majors who are sophomores, 15 computer science majors who are sophomores, 2 mathematics majors who are juniors, 2 computer science majors who are juniors, and 1 computer science major who is a senior. Express each of these statements in terms of quantifiers and then determine its truth value. a) There is a student in the class who is a junior. b) Every student in the class is a computer science major. c) There is a student in the class who is neither a mathematics major nor a junior. d) Every student in the class is either a sophomore or a computer science major. e) There is a major such that there is a student in the class in every year of study with that major.",
