    "rawText": "36. Express each of these statements using quantiﬁers. Then\nform the negation of the statement so that no negation is\nto the left of a quantiﬁer. Next, express the negation in\nsimple English. (Do not simply use the phrase “It is not\nthe case that.”)\na) No one has lost more than one thousand dollars play-\ning the lottery.\nb) There is a student in this class who has chatted with\nexactly one other student.\n72 1 / The Foundations: Logic and Proofs\nc) No student in this class has sent e-mail to exactly two\nother students in this class.\nd) Some student has solved every exercise in this book.\ne) No student has solved at least one exercise in every\nsection of this book.",
    "prompt": "36. Express each of these statements using quantifiers. Then form the negation of the statement so that no negation is to the left of a quantifier. Next, express the negation in simple English. (Do not simply use the phrase “It is not the case that.”) a) No one has lost more than one thousand dollars playing the lottery. b) There is a student in this class who has chatted with exactly one other student. c) No student in this class has sent e-mail to exactly two other students in this class. d) Some student has solved every exercise in this book. e) No student has solved at least one exercise in every section of this book.",
