    "number": 48,
    "difficulty": "challenging",
    "stars": 1,
    "rawText": "∗48. Show that ∀xP(x)∨∀xQ(x)a n d ∀x∀y(P(x)∨Q(y)),\nwhere all quantiﬁers have the same nonempty domain,\nare logically equivalent. (The new variable y is used to\ncombine the quantiﬁcations correctly.)",
