    "rawText": "3. What rule of inference is used in each of these argu-\nments?\na) Alice is a mathematics major. Therefore, Alice is ei-\nther a mathematics major or a computer science ma-\njor.\nb) Jerry is a mathematics major and a computer science\nmajor. Therefore, Jerry is a mathematics major.\nc) If it is rainy, then the pool will be closed. It is rainy.\nTherefore, the pool is closed.\nd) If it snows today, the university will close. The uni-\nversity is not closed today. Therefore, it did not snow\ntoday.\ne) If I go swimming, then I will stay in the sun too long.\nIf I stay in the sun too long, then I will sunburn. There-\nfore, if I go swimming, then I will sunburn.",
    "prompt": "3. What rule of inference is used in each of these arguments? a) Alice is a mathematics major. Therefore, Alice is either a mathematics major or a computer science major. b) Jerry is a mathematics major and a computer science major. Therefore, Jerry is a mathematics major. c) If it is rainy, then the pool will be closed. It is rainy. Therefore, the pool is closed. d) If it snows today, the university will close. The university is not closed today. Therefore, it did not snow today. e) If I go swimming, then I will stay in the sun too long. If I stay in the sun too long, then I will sunburn. Therefore, if I go swimming, then I will sunburn.",
