    "number": 4,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "4. What rule of inference is used in each of these argu-\nments?\na) Kangaroos live in Australia and are marsupials.\nTherefore, kangaroos are marsupials.\nb) It is either hotter than 100 degrees today or the pollu-\ntion is dangerous. It is less than 100 degrees outside\ntoday. Therefore, the pollution is dangerous.\nc) Linda is an excellent swimmer. If Linda is an ex-\ncellent swimmer, then she can work as a lifeguard.\nTherefore, Linda can work as a lifeguard.\nd) Steve will work at a computer company this summer.\nTherefore, this summer Steve will work at a computer\ncompany or he will be a beach bum.\ne) If I work all night on this homework, then I can an-\nswer all the exercises. If I answer all the exercises, I\nwill understand the material. Therefore, if I work all\nnight on this homework, then I will understand the\nmaterial.",
    "prompt": "4. What rule of inference is used in each of these arguments? a) Kangaroos live in Australia and are marsupials. Therefore, kangaroos are marsupials. b) It is either hotter than 100 degrees today or the pollution is dangerous. It is less than 100 degrees outside today. Therefore, the pollution is dangerous. c) Linda is an excellent swimmer. If Linda is an excellent swimmer, then she can work as a lifeguard. Therefore, Linda can work as a lifeguard. d) Steve will work at a computer company this summer. Therefore, this summer Steve will work at a computer company or he will be a beach bum. e) If I work all night on this homework, then I can answer all the exercises. If I answer all the exercises, I will understand the material. Therefore, if I work all night on this homework, then I will understand the material.",
