    "rawText": "14. For each of these arguments, explain which rules of in-\nference are used for each step.\na) “Linda, a student in this class, owns a red convertible.\nEveryone who owns a red convertible has gotten at\nleast one speeding ticket. Therefore, someone in this\nclass has gotten a speeding ticket.”\nb) “Each of ﬁve roommates, Melissa, Aaron, Ralph, Ve-\nneesha, and Keeshawn, has taken a course in discrete\nmathematics. Every student who has taken a course in\ndiscrete mathematics can take a course in algorithms.\nTherefore, all ﬁve roommates can take a course in al-\ngorithms next year.”\nc) “All movies produced by John Sayles are wonder-\nful. John Sayles produced a movie about coal min-\ners. Therefore, there is a wonderful movie about coal\nminers.”\nd) “There is someone in this class who has been to\nFrance. Everyone who goes to France visits the\nLouvre. Therefore, someone in this class has visited\nthe Louvre.”",
    "prompt": "14. For each of these arguments, explain which rules of inference are used for each step. a) “Linda, a student in this class, owns a red convertible. Everyone who owns a red convertible has gotten at least one speeding ticket. Therefore, someone in this class has gotten a speeding ticket.” b) “Each of five roommates, Melissa, Aaron, Ralph, Veneesha, and Keeshawn, has taken a course in discrete mathematics. Every student who has taken a course in discrete mathematics can take a course in algorithms. Therefore, all five roommates can take a course in algorithms next year.” c) “All movies produced by John Sayles are wonderful. John Sayles produced a movie about coal miners. Therefore, there is a wonderful movie about coal miners.” d) “There is someone in this class who has been to France. Everyone who goes to France visits the Louvre. Therefore, someone in this class has visited the Louvre.”",
