    "setId": "rosen-ch1-exercise-set-1-6",
    "section": "1.6",
    "number": 34,
    "difficulty": "challenging",
    "stars": 1,
    "rawText": "∗34. The Logic Problem, taken from WFF’N PROOF, The\nGame of Logic, has these two assumptions:\n1. “Logic is diﬃcult or not many students like logic.”\n2. “If mathematics is easy, then logic is not diﬃcult.”\nBy translating these assumptions into statements involv-\ning propositional variables and logical connectives, de-\ntermine whether each of the following are valid conclu-\nsions of these assumptions:\na) That mathematics is not easy, if many students like\nlogic.\nb) That not many students like logic, if mathematics is\nnot easy.\nc) That mathematics is not easy or logic is diﬃcult.\nd) That logic is not diﬃcult or mathematics is not easy.\ne) That if not many students like logic, then either math-\nematics is not easy or logic is not diﬃcult.",
    "prompt": "∗34. The Logic Problem, taken from WFF’N PROOF, The Game of Logic, has these two assumptions: 1. “Logic is difficult or not many students like logic.” 2. “If mathematics is easy, then logic is not difficult.” By translating these assumptions into statements involving propositional variables and logical connectives, determine whether each of the following are valid conclusions of these assumptions: a) That mathematics is not easy, if many students like logic. b) That not many students like logic, if mathematics is not easy. c) That mathematics is not easy or logic is difficult. d) That logic is not difficult or mathematics is not easy. e) That if not many students like logic, then either mathematics is not easy or logic is not difficult.",
