    "section": "1.7",
    "number": 36,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "36. Is this reasoning for ﬁnding the solutions of the equa-\ntion\n√\n2x2 −1 = x correct? (1)\n√\n2x2 −1 = x is given;\n(2) 2x2 −1 = x2, obtained by squaring both sides of (1);\n(3) x2 −1 = 0, obtained by subtracting x2 from both\nsides of (2); (4) (x −1)(x+ 1) = 0, obtained by factor-\ning the left-hand side of x2 −1; (5) x = 1o r x =−1,\nwhich follows because ab = 0 implies that a = 0o r\nb = 0.",
    "prompt": "36. Is this reasoning for finding the solutions of the equation √ 2x2 −1 = x correct? (1) √ 2x2 −1 = x is given; (2) 2x2 −1 = x2, obtained by squaring both sides of (1); (3) x2 −1 = 0, obtained by subtracting x2 from both sides of (2); (4) (x −1)(x+ 1) = 0, obtained by factoring the left-hand side of x2 −1; (5) x = 1o r x =−1, which follows because ab = 0 implies that a = 0o r b = 0.",
