    "number": 47,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "47. Use a proof by exhaustion to show that a tiling using\ndominoes of a 4× 4 checkerboard with opposite corners\nremoved does not exist. [Hint: First show that you can\nassume that the squares in the upper left and lower right\ncorners are removed. Number the squares of the original\ncheckerboard from 1 to 16, starting in the ﬁrst row, mov-\ning right in this row, then starting in the leftmost square\nin the second row and moving right, and so on. Remove\nsquares 1 and 16. To begin the proof, note that square\n2 is covered either by a domino laid horizontally, which\nK e yT e r m sa n dR e s u l t s115\ncovers squares 2 and 3, or vertically, which covers squares\n2 and 6. Consider each of these cases separately, and work\nthrough all the subcases that arise.]",
    "prompt": "47. Use a proof by exhaustion to show that a tiling using dominoes of a 4× 4 checkerboard with opposite corners removed does not exist. [Hint: First show that you can assume that the squares in the upper left and lower right corners are removed. Number the squares of the original checkerboard from 1 to 16, starting in the first row, moving right in this row, then starting in the leftmost square in the second row and moving right, and so on. Remove squares 1 and 16. To begin the proof, note that square 2 is covered either by a domino laid horizontally, which covers squares 2 and 3, or vertically, which covers squares 2 and 6. Consider each of these cases separately, and work through all the subcases that arise.]",
