    "stars": 0,
    "rawText": "1. Let p be the proposition “I will do every exercise in\nthis book” and q be the proposition “I will get an A in\nthis course.” Express each of these as a combination of\np and q.\na) I will get an A in this course only if I do every exercise\nin this book.\nb) I will get an A in this course and I will do every exer-\ncise in this book.\nc) Either I will not get an A in this course or I will not\ndo every exercise in this book.\nd) For me to get an A in this course it is necessary and\nsuﬃcient that I do every exercise in this book.",
    "prompt": "1. Let p be the proposition “I will do every exercise in this book” and q be the proposition “I will get an A in this course.” Express each of these as a combination of p and q. a) I will get an A in this course only if I do every exercise in this book. b) I will get an A in this course and I will do every exercise in this book. c) Either I will not get an A in this course or I will not do every exercise in this book. d) For me to get an A in this course it is necessary and sufficient that I do every exercise in this book.",
