    "setId": "rosen-ch1-exercise-set-supplementary",
    "section": null,
    "number": 9,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "9. Show that these statements are inconsistent: “If Miranda\ndoes not take a course in discrete mathematics, then she\nwill not graduate.” “If Miranda does not graduate, then\nshe is not qualiﬁed for the job.” “If Miranda reads this\nbook, then she is qualiﬁed for the job.” “Miranda does\nnot take a course in discrete mathematics but she reads\nthis book.”\nTeachers in the Middle Ages supposedly tested the realtime\npropositional logic ability of a student via a technique known\nas an obligato game. In an obligato game, a number of rounds\nis set and in each round the teacher gives the student succes-\nsive assertions that the student must either accept or reject as\nthey are given. When the student accepts an assertion, it is\n118 1 / The Foundations: Logic and Proofs\nadded as a commitment; when the student rejects an assertion\nits negation is added as a commitment. The student passes\nthe test if the consistency of all commitments is maintained\nthroughout the test.",
    "prompt": "9. Show that these statements are inconsistent: “If Miranda does not take a course in discrete mathematics, then she will not graduate.” “If Miranda does not graduate, then she is not qualified for the job.” “If Miranda reads this book, then she is qualified for the job.” “Miranda does not take a course in discrete mathematics but she reads this book.” Teachers in the Middle Ages supposedly tested the realtime propositional logic ability of a student via a technique known as an obligato game. In an obligato game, a number of rounds is set and in each round the teacher gives the student successive assertions that the student must either accept or reject as they are given. When the student accepts an assertion, it is added as a commitment; when the student rejects an assertion its negation is added as a commitment. The student passes the test if the consistency of all commitments is maintained throughout the test.",
