    "number": 15,
    "difficulty": "standard",
    "stars": 0,
    "rawText": "15. (Adapted from [Sm78]) Suppose that on an island there\nare three types of people, knights, knaves, and normals\n(also known as spies). Knights always tell the truth,\nknaves always lie, and normals sometimes lie and some-\ntimes tell the truth. Detectives questioned three inhabi-\ntants of the island—Amy, Brenda, and Claire—as part of\nthe investigation of a crime. The detectives knew that one\nof the three committed the crime, but not which one. They\nalso knew that the criminal was a knight, and that the\nother two were not. Additionally, the detectives recorded\nthese statements: Amy: “I am innocent.” Brenda: “What\nAmy says is true.” Claire: “Brenda is not a normal.” Af-\nter analyzing their information, the detectives positively\nidentiﬁed the guilty party. Who was it?",
    "prompt": "15. (Adapted from [Sm78]) Suppose that on an island there are three types of people, knights, knaves, and normals (also known as spies). Knights always tell the truth, knaves always lie, and normals sometimes lie and sometimes tell the truth. Detectives questioned three inhabitants of the island—Amy, Brenda, and Claire—as part of the investigation of a crime. The detectives knew that one of the three committed the crime, but not which one. They also knew that the criminal was a knight, and that the other two were not. Additionally, the detectives recorded these statements: Amy: “I am innocent.” Brenda: “What Amy says is true.” Claire: “Brenda is not a normal.” After analyzing their information, the detectives positively identified the guilty party. Who was it?",
